nested_token_objects.example:
>theme = {
    primary: #87CC2E,
    surface: #152018,
    border: alpha(#87CC2E, 0.25)
};
rect #badge {
    fill: >theme.surface;
    stroke: >theme.border 1px;
}

calc_function.example:
rect #wideCard {
    width: calc(100% - 80px);
    height: calc(50% - 40px);
    at: (40px, 40px);
}
rect #modalBox {
    width: calc(>gridBase * 60);
    padding: calc(>gridBase * 2);
}
